//
//  SEBBrowserControllerTrustTests.swift
//  SafeExamBrowserTests
//
//  Regression tests for the server-trust authorization decision in
//  +[SEBBrowserController shouldAuthorizeServerTrust:...], guarding the removed
//  authorizedHosts substring bypass (CWE-295): a previously successful trust
//  evaluation must NEVER authorize a later failed evaluation, regardless of any
//  host relationship (same host, subdomain, non-label substring, attacker suffix)
//  and regardless of pinEmbeddedCertificates.
//
//  The certificates are fixtures generated by scripts/gen-trust-test-fixtures.sh
//  (a test CA plus leaves). Leaves carry EKU serverAuth + a SAN and are valid for
//  397 days (<= Apple's 398-day TLS limit); only the root CA is long-lived. The
//  "expired" leaf is intentionally expired. Regenerate with the script if they age
//  out (~2027-09), pasting the new base64 over the constants below.
//
//  Uses XCTest to match the other unit tests in this target.
//

import XCTest
import Safe_Exam_Browser

final class SEBBrowserControllerTrustTests: XCTestCase {

    // MARK: - Fixtures (base64 DER, see scripts/gen-trust-test-fixtures.sh)

    // Test root CA (self-signed, CA:TRUE).
    private let caB64 = ""

    // Valid leaf for example.test, chaining to the test CA.
    private let validExampleB64 = ""

    // Valid leaf for sub.example.test, chaining to the test CA.
    private let validSubB64 = ""

    // CA-signed leaf whose only SAN is other.test (wrong host for example.test).
    private let wrongHostB64 = ""

    // CA-signed leaf for example.test, but valid only 2000..2001 (expired).
    private let expiredB64 = ""

    // Self-signed leaf for example.test (unknown CA).
    private let selfSignedB64 = ""

    // MARK: - Helpers

    private func der(_ b64: String, _ file: StaticString = #filePath, _ line: UInt = #line) -> Data {
        guard let data = Data(base64Encoded: b64) else {
            XCTFail("Invalid base64 fixture", file: file, line: line)
            return Data()
        }
        return data
    }

    /// Runs the production decision. `caCerts`/`tlsCerts`/`debugCerts` default to empty.
    private func authorize(leaf: String,
                           host: String,
                           port: Int = 443,
                           caCerts: [String] = [],
                           tlsCerts: [String] = [],
                           debugCerts: [String] = [],
                           debugCertNames: [String] = [],
                           pinEmbedded: Bool) -> Bool {
        SEBBrowserControllerTrustTestSupport.authorizeServerPresentingLeaf(
            der(leaf),
            host: host,
            port: port,
            caCertsDER: caCerts.map { der($0) },
            tlsCertsDER: tlsCerts.map { der($0) },
            debugCertsDER: debugCerts.map { der($0) },
            debugCertNames: debugCertNames,
            pinEmbeddedCertificates: pinEmbedded)
    }

    // MARK: - Legitimate accept paths (must keep working)

    // Valid leaf chaining to the embedded CA, not pinned.
    func testValidCertChainingToEmbeddedCA_isAuthorized() {
        for pin in [false, true] {
            XCTAssertTrue(authorize(leaf: validExampleB64, host: "example.test",
                                    caCerts: [caB64], pinEmbedded: pin),
                          "valid CA-chained cert must be authorized (pin=\(pin))")
        }
    }

    // A valid subdomain leaf chaining to the embedded CA.
    func testValidSubdomainCert_isAuthorized() {
        XCTAssertTrue(authorize(leaf: validSubB64, host: "sub.example.test",
                                caCerts: [caB64], pinEmbedded: false))
    }

    // Exact public-key pin of a self-signed cert.
    func testExactPublicKeyPin_isAuthorized() {
        XCTAssertTrue(authorize(leaf: selfSignedB64, host: "example.test",
                                tlsCerts: [selfSignedB64], pinEmbedded: true),
                      "server cert whose public key is pinned must be authorized")
    }

    // MARK: - Rejections (independent of any prior success)

    func testUnknownCASelfSigned_isRejected() {
        for pin in [false, true] {
            XCTAssertFalse(authorize(leaf: selfSignedB64, host: "example.test",
                                     caCerts: [caB64], pinEmbedded: pin),
                           "self-signed (unknown CA) cert must be rejected (pin=\(pin))")
        }
    }

    func testExpiredCert_isRejected() {
        for pin in [false, true] {
            XCTAssertFalse(authorize(leaf: expiredB64, host: "example.test",
                                     caCerts: [caB64], pinEmbedded: pin),
                           "expired cert must be rejected (pin=\(pin))")
        }
    }

    func testHostnameMismatch_isRejected() {
        // CA-signed, but the certificate is for other.test.
        for pin in [false, true] {
            XCTAssertFalse(authorize(leaf: wrongHostB64, host: "example.test",
                                     caCerts: [caB64], pinEmbedded: pin),
                           "wrong-host cert must be rejected (pin=\(pin))")
        }
    }

    func testPinnedButPublicKeyMismatch_isRejected() {
        // Pinning a different cert must not authorize the presented self-signed cert.
        XCTAssertFalse(authorize(leaf: selfSignedB64, host: "example.test",
                                 tlsCerts: [validExampleB64], pinEmbedded: true))
    }

    // MARK: - CWE-295 regression: no cross-connection host fallback

    // The core of the reported vulnerability: after example.test was validated with
    // a good cert, a failing cert for the SAME host must still be rejected. Because
    // the decision is stateless the prior success cannot leak in — assert both.
    func testValidThenInvalidSameHost_secondIsRejected() {
        for pin in [false, true] {
            XCTAssertTrue(authorize(leaf: validExampleB64, host: "example.test",
                                    caCerts: [caB64], pinEmbedded: pin))
            XCTAssertFalse(authorize(leaf: selfSignedB64, host: "example.test",
                                     caCerts: [caB64], pinEmbedded: pin),
                           "a prior success must not authorize a later failed cert for the same host (pin=\(pin))")
        }
    }

    // A failing cert for a real subdomain must be rejected even after the parent
    // domain was validated.
    func testInvalidCertForRealSubdomain_isRejected() {
        XCTAssertTrue(authorize(leaf: validExampleB64, host: "example.test",
                                caCerts: [caB64], pinEmbedded: false))
        // self-signed example.test cert presented for host sub.example.test:
        // unknown CA + hostname mismatch.
        XCTAssertFalse(authorize(leaf: selfSignedB64, host: "sub.example.test",
                                 caCerts: [caB64], pinEmbedded: false))
    }

    // A host containing the trusted host as a NON-LABEL substring (the old predicate
    // matched this). Present the CA-signed example.test cert for notexample.test:
    // chains to the CA but the hostname does not match -> must be rejected.
    func testNonLabelSubstringHost_isRejected() {
        XCTAssertTrue(authorize(leaf: validExampleB64, host: "example.test",
                                caCerts: [caB64], pinEmbedded: false))
        XCTAssertFalse(authorize(leaf: validExampleB64, host: "notexample.test",
                                 caCerts: [caB64], pinEmbedded: false),
                       "hostname mismatch must be rejected even though 'notexample.test' contains 'example.test'")
    }

    // The attacker-suffix case example.test.attacker.test.
    func testAttackerSuffixHost_isRejected() {
        XCTAssertTrue(authorize(leaf: validExampleB64, host: "example.test",
                                caCerts: [caB64], pinEmbedded: false))
        XCTAssertFalse(authorize(leaf: validExampleB64, host: "example.test.attacker.test",
                                 caCerts: [caB64], pinEmbedded: false),
                       "hostname mismatch must be rejected for an attacker suffix domain")
    }
}
